record.field:
role = env.ref("budget_role.role_budget_commitment", raise_if_not_found=False)
act_type = env.ref("purchase_request_approval_todo.mail_activity_pa_awaiting_manager", raise_if_not_found=False)
if act_type:
    for rec in records:
        if rec.activity_ids.filtered(lambda a: a.activity_type_id == act_type):
            continue
        pr = rec.request_id
        sender = pr.assigned_to if pr else env["res.users"]
        if not sender:
            sender = rec.user_id
        sender_name = sender.name if sender else "เจ้าหน้าที่พัสดุ"
        summary = "ท่านได้รับ แบบรายงานขอให้จัดซื้อจัดจ้าง (พจ.1) จาก %s เพื่อให้ท่านดำเนินการ พิจารณา" % sender_name
        ou = rec.operating_unit_id if "operating_unit_id" in rec._fields else False
        if role and ou:
            rec.activity_schedule(
                "purchase_request_approval_todo.mail_activity_pa_awaiting_manager",
                summary=summary,
                responsible_role_id=role.id,
                operating_unit_id=ou.id,
            )
        elif rec.assigned_to:
            rec.activity_schedule(
                "purchase_request_approval_todo.mail_activity_pa_awaiting_manager",
                summary=summary,
                user_id=rec.assigned_to.id,
            )
